// AuthServiceHandler is an implementation of the everstack.auth.v1.AuthService service.
type AuthServiceHandler interface {
	// GetSession returns the current user session if authenticated
	GetSession(context.Context, *connect.Request[v1.GetSessionRequest]) (*connect.Response[v1.GetSessionResponse], error)
	// GetAuthURL returns the SSO provider URL for sign-in redirect (Cloud only)
	GetAuthURL(context.Context, *connect.Request[v1.GetAuthURLRequest]) (*connect.Response[v1.GetAuthURLResponse], error)
	// Authenticate exchanges an OAuth code for a session (Cloud only)
	Authenticate(context.Context, *connect.Request[v1.AuthenticateRequest]) (*connect.Response[v1.AuthenticateResponse], error)
	// SignOut invalidates the current session
	SignOut(context.Context, *connect.Request[v1.SignOutRequest]) (*connect.Response[v1.SignOutResponse], error)
	// RefreshSession extends the current session
	RefreshSession(context.Context, *connect.Request[v1.RefreshSessionRequest]) (*connect.Response[v1.RefreshSessionResponse], error)
	// CreateInstanceConnectSession creates a short-lived session for connecting
	// a CE instance to Everstack Cloud.
	CreateInstanceConnectSession(context.Context, *connect.Request[v1.CreateInstanceConnectSessionRequest]) (*connect.Response[v1.CreateInstanceConnectSessionResponse], error)
	// GetInstanceConnectSession validates and returns metadata for an instance
	// connection session.
	GetInstanceConnectSession(context.Context, *connect.Request[v1.GetInstanceConnectSessionRequest]) (*connect.Response[v1.GetInstanceConnectSessionResponse], error)
	// CompleteInstanceConnect binds an authenticated cloud organization to the
	// instance and returns the redirect URL back to the instance.
	CompleteInstanceConnect(context.Context, *connect.Request[v1.CompleteInstanceConnectRequest]) (*connect.Response[v1.CompleteInstanceConnectResponse], error)
	// CreateDeviceAuthorization initiates a device authorization flow.
	// The CLI/desktop calls this to get a user code and verification URL.
	CreateDeviceAuthorization(context.Context, *connect.Request[v1.CreateDeviceAuthorizationRequest]) (*connect.Response[v1.CreateDeviceAuthorizationResponse], error)
	// ExchangeDeviceCode polls for the result of a device authorization.
	// Returns pending until the user approves in the browser.
	ExchangeDeviceCode(context.Context, *connect.Request[v1.ExchangeDeviceCodeRequest]) (*connect.Response[v1.ExchangeDeviceCodeResponse], error)
	// ApproveDeviceAuthorization approves a device authorization request.
	// Called by the browser after the user confirms.
	ApproveDeviceAuthorization(context.Context, *connect.Request[v1.ApproveDeviceAuthorizationRequest]) (*connect.Response[v1.ApproveDeviceAuthorizationResponse], error)
	// GetDeviceAuthorizationStatus returns the status of a device authorization by user code.
	// Used by the browser approval page to validate the code.
	GetDeviceAuthorizationStatus(context.Context, *connect.Request[v1.GetDeviceAuthorizationStatusRequest]) (*connect.Response[v1.GetDeviceAuthorizationStatusResponse], error)
	// GetAuthMode returns the authentication mode (cloud vs self-hosted)
	GetAuthMode(context.Context, *connect.Request[v1.GetAuthModeRequest]) (*connect.Response[v1.GetAuthModeResponse], error)
	// Register creates the first admin user (becomes instance owner) - Self-hosted only
	Register(context.Context, *connect.Request[v1.RegisterRequest]) (*connect.Response[v1.RegisterResponse], error)
	// Login authenticates with email and password - Self-hosted only
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	// RequestMagicLink sends a magic link email for passwordless login - Self-hosted only
	RequestMagicLink(context.Context, *connect.Request[v1.RequestMagicLinkRequest]) (*connect.Response[v1.RequestMagicLinkResponse], error)
	// VerifyMagicLink verifies a magic link token and creates a session - Self-hosted only
	VerifyMagicLink(context.Context, *connect.Request[v1.VerifyMagicLinkRequest]) (*connect.Response[v1.VerifyMagicLinkResponse], error)
	// RequestPasswordReset initiates a password reset by emailing a reset link
	// to the user. Anti-enumeration: always returns success.
	RequestPasswordReset(context.Context, *connect.Request[v1.RequestPasswordResetRequest]) (*connect.Response[v1.RequestPasswordResetResponse], error)
	// CompletePasswordReset finalises a password reset using the token from the
	// email and creates a session.
	CompletePasswordReset(context.Context, *connect.Request[v1.CompletePasswordResetRequest]) (*connect.Response[v1.CompletePasswordResetResponse], error)
	// CompleteEmailVerification finalises email verification using the
	// pending_authentication_token from a prior auth challenge and the code
	// delivered by email.
	CompleteEmailVerification(context.Context, *connect.Request[v1.CompleteEmailVerificationRequest]) (*connect.Response[v1.CompleteEmailVerificationResponse], error)
	// InviteTeamMember sends an invitation to join the team (checks seat limit)
	InviteTeamMember(context.Context, *connect.Request[v1.InviteTeamMemberRequest]) (*connect.Response[v1.InviteTeamMemberResponse], error)
	// AcceptInvitation accepts a team invitation and sets up the user account
	AcceptInvitation(context.Context, *connect.Request[v1.AcceptInvitationRequest]) (*connect.Response[v1.AcceptInvitationResponse], error)
	// ListTeamMembers returns all team members and pending invitations
	ListTeamMembers(context.Context, *connect.Request[v1.ListTeamMembersRequest]) (*connect.Response[v1.ListTeamMembersResponse], error)
	// RemoveTeamMember removes a user from the team
	RemoveTeamMember(context.Context, *connect.Request[v1.RemoveTeamMemberRequest]) (*connect.Response[v1.RemoveTeamMemberResponse], error)
	// RevokeInvitation revokes a pending invitation
	RevokeInvitation(context.Context, *connect.Request[v1.RevokeInvitationRequest]) (*connect.Response[v1.RevokeInvitationResponse], error)
}

